# ---------------------------------------------------------------- fonts
# 1-bit bitmap fonts rasterised at build time from Liberation fonts.
# Each blob: glyphs in codepoint order; each glyph = 1 width byte +
# ceil(width/8)*height bitmap bytes (MSB-first, row-major).
# CHARS covers ASCII 32-126 plus middle dot, em dash, right quote, euro.
CHARS = [chr(c) for c in range(32, 127)] + ["\u00b7", "\u2014", "\u2019", "\u20ac"]
# Masthead serif only ever renders "Sunday 22 November 2026", so its
# blob covers just those characters (codepoint order).
SERIF_CHARS = " 0126NSabdemnortuvy"

F_SANS10 = ""
F_SANS12 = ""
F_SANSB10 = ""
F_SANSB15 = ""
F_SANSB22 = ""
F_SERIFB48 = ""

# Expected decoded sizes (integrity check).
_FONT_SPECS = [
    ("sans10", CHARS, 13, F_SANS10, 1464),
    ("sans12", CHARS, 14, F_SANS12, 1709),
    ("sansb10", CHARS, 13, F_SANSB10, 1464),
    ("sansb15", CHARS, 18, F_SANSB15, 3123),
    ("sansb22", CHARS, 25, F_SANSB22, 4699),
    ("serif48", SERIF_CHARS, 54, F_SERIFB48, 3475),
]


def _load_fonts():
    """Decode the bitmap blobs into {name: (height, {char: (w, bytes)})}."""
    fonts = {}
    for name, chars, height, blob, expect in _FONT_SPECS:
        raw = base64.b64decode(blob)
        if len(raw) != expect:
            raise ValueError("font %s decoded to %d bytes, expected %d"
                             % (name, len(raw), expect))
        glyphs = {}
        pos = 0
        for ch in chars:
            w = raw[pos]
            pos += 1
            rowbytes = (w + 7) // 8
            glyphs[ch] = (w, raw[pos:pos + rowbytes * height])
            pos += rowbytes * height
        if pos != len(raw):
            raise ValueError("font %s parse ended at %d of %d"
                             % (name, pos, len(raw)))
        fonts[name] = (height, glyphs)
    return fonts


