MADAGASCAR = [(44, -16), (47, -15), (50, -16), (49, -20), (47, -24),
    (45, -25), (44, -22), (43, -18), (44, -16)]
CONTINENTS = [NORTH_AMERICA, GREENLAND, ICELAND, SOUTH_AMERICA, AFRICA,
    EURASIA, UK, JAPAN, SUMATRA, BORNEO, JAVA, NEW_GUINEA, AUSTRALIA,
    NEW_ZEALAND, MADAGASCAR]

# ---------------------------------------------------------------- drawing
def frame(cv, x, y, w, h, c):
    cv.rect(x, y, w, 1, c)
    cv.rect(x, y + h - 1, w, 1, c)
    cv.rect(x, y, 1, h, c)
    cv.rect(x + w - 1, y, 1, h, c)


def starburst(cv, cx, cy, r, c):
    import math
    for i in range(8):
        a = math.pi * i / 4
        cv.line(cx, cy, int(cx + r * math.cos(a)), int(cy + r * math.sin(a)), c)
    cv.circle(cx, cy, max(2, r // 4), c)


def quad_arc(cv, p0, p1, p2, c, steps=24):
    prev = p0
    for i in range(1, steps + 1):
        t = i / steps
        x = (1 - t) * (1 - t) * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0]
        y = (1 - t) * (1 - t) * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1]
        cur = (int(x), int(y))
        cv.line(prev[0], prev[1], cur[0], cur[1], c)
        prev = cur


def draw_icon(cv, kind, x, y):
    """Small geometric pictogram in a 28x28 box at (x, y)."""
    if kind == "flame":
        cv.poly([(14 + x, 2 + y), (22 + x, 14 + y), (18 + x, 26 + y),
                 (10 + x, 26 + y), (6 + x, 14 + y)], BURST)
        cv.poly([(14 + x, 12 + y), (18 + x, 20 + y), (14 + x, 25 + y),
                 (10 + x, 20 + y)], GOLD)
    elif kind == "missile":
        cv.line(x + 4, y + 24, x + 22, y + 6, INK)
        cv.poly([(x + 22, y + 6), (x + 26, y + 10), (x + 18, y + 12)], RED)
        cv.line(x + 8, y + 20, x + 4, y + 26, INK)
        cv.line(x + 12, y + 22, x + 6, y + 22, INK)
    elif kind == "burst":
        starburst(cv, x + 14, y + 14, 12, BURST)
        cv.circle(x + 14, y + 14, 3, GOLD)
    elif kind == "globe":
        cv.ring(x + 14, y + 14, 11, NAVY)
        cv.line(x + 3, y + 14, x + 25, y + 14, NAVY)
        cv.line(x + 14, y + 3, x + 14, y + 25, NAVY)
        cv.rect(x + 8, y + 8, 12, 1, NAVY)
        cv.rect(x + 8, y + 19, 12, 1, NAVY)
    elif kind == "flags":
        cv.line(x + 7, y + 4, x + 7, y + 26, INK)
        cv.line(x + 19, y + 4, x + 19, y + 26, INK)
        cv.poly([(x + 7, y + 4), (x + 17, y + 7), (x + 7, y + 11)], RED)
        cv.poly([(x + 19, y + 4), (x + 27, y + 7), (x + 19, y + 11)], NAVY)
    elif kind == "summit":
        cv.circle(x + 7, y + 20, 3, NAVY)
        cv.circle(x + 14, y + 8, 3, RED)
        cv.circle(x + 21, y + 20, 3, NAVY)
        cv.line(x + 7, y + 20, x + 14, y + 8, INK)
        cv.line(x + 14, y + 8, x + 21, y + 20, INK)
        cv.line(x + 7, y + 20, x + 21, y + 20, INK)
    elif kind == "pin":
        cv.circle(x + 14, y + 10, 8, RED)
        cv.poly([(x + 8, y + 14), (x + 20, y + 14), (x + 14, y + 26)], RED)
        cv.circle(x + 14, y + 10, 3, WHITE)
    elif kind == "chip":
        cv.rect(x + 7, y + 7, 14, 14, NAVY)
        cv.rect(x + 11, y + 11, 6, 6, GOLD)
        for dx in (9, 14, 19):
            cv.rect(x + dx, y + 3, 2, 4, INK)
            cv.rect(x + dx, y + 21, 2, 4, INK)
        for dy in (9, 14, 19):
            cv.rect(x + 3, y + dy, 4, 2, INK)
            cv.rect(x + 21, y + dy, 4, 2, INK)
    elif kind == "bars":
        cv.rect(x + 4, y + 18, 5, 8, NAVY)
        cv.rect(x + 12, y + 12, 5, 14, RED)
        cv.rect(x + 20, y + 5, 5, 21, GOLD)
    elif kind == "tank":
        cv.rect(x + 4, y + 12, 18, 8, NAVY)
        cv.line(x + 20, y + 15, x + 27, y + 15, INK)
        cv.circle(x + 8, y + 22, 2, INK)
        cv.circle(x + 14, y + 22, 2, INK)
        cv.circle(x + 20, y + 22, 2, INK)
    elif kind == "gavel":
        cv.line(x + 6, y + 24, x + 20, y + 10, INK)
        cv.rect(x + 16, y + 4, 10, 6, NAVY)
        cv.rect(x + 4, y + 24, 8, 2, INK)
    elif kind == "crown":
        cv.poly([(x + 5, y + 22), (x + 5, y + 10), (x + 10, y + 15),
                 (x + 14, y + 6), (x + 18, y + 15), (x + 23, y + 10),
                 (x + 23, y + 22)], GOLD)
        cv.rect(x + 5, y + 22, 18, 3, GOLD)


def draw_lead_art1(cv, x, y, w, h):
    cv.rect(x, y, w, h, NAVY)
    cv.poly([(x + 30, y + 30), (x + 120, y + 14), (x + 210, y + 28),
             (x + 290, y + 20), (x + 305, y + 55), (x + 260, y + 88),
             (x + 170, y + 98), (x + 80, y + 92), (x + 25, y + 62)], LAND)
    quad_arc(cv, (x + 300, y + 30), (x + 210, y + 5), (x + 120, y + 55), RED)
    quad_arc(cv, (x + 310, y + 70), (x + 235, y + 40), (x + 150, y + 75), RED)
    cv.circle(x + 120, y + 55, 3, WHITE)
    cv.circle(x + 150, y + 75, 3, WHITE)
    starburst(cv, x + 120, y + 55, 12, BURST)
    starburst(cv, x + 150, y + 75, 10, GOLD)


def draw_lead_art2(cv, x, y, w, h):
    cv.rect(x, y, w, h, DUSK)
    heights = [34, 52, 44, 66, 58, 74, 48, 62, 40, 56, 70, 46]
    bw = w // len(heights)
    for i, hh in enumerate(heights):
        cv.rect(x + i * bw, y + h - hh, bw - 2, hh, SKYLINE)
    quad_arc(cv, (x + 20, y + h - 30), (x + 162, y + h - 78),
             (x + 304, y + h - 30), GOLD)
    for vx in range(50, 300, 42):
        cv.line(x + vx, y + h - 30, x + vx, y + h - 52, GOLD)
    starburst(cv, x + 90, y + 42, 13, BURST)
    starburst(cv, x + 225, y + 58, 11, GOLD)
    cv.circle(x + 78, y + 30, 4, GREY)
    cv.circle(x + 238, y + 46, 4, GREY)


def draw_lead_art3(cv, tx, x, y, w, h):
    cv.rect(x, y, w, h, CREAM)
    for gx in range(x + 40, x + w, 40):
        cv.vline(gx, y, y + h, (224, 214, 190))
    for gy in range(y + 28, y + h, 28):
        cv.hline(x, x + w, gy, (224, 214, 190))
    # night street in Guasave: road, burning barricades, buildings
    cv.rect(x, y + 78, w, 34, (52, 52, 52))
    cv.rect(x, y + 92, w, 2, GOLD)
    for bx in (18, 78, 138, 198, 258):
        cv.rect(x + bx, y + 34, 44, 44, NAVY)
        cv.rect(x + bx + 8, y + 46, 10, 10, GOLD)
        cv.rect(x + bx + 26, y + 46, 10, 10, GOLD)
    for fx in (60, 160, 260):
        starburst(cv, x + fx, y + 88, 11, BURST)
    tx.draw(cv, "sansb10", x + 8, y + 6, "GUASAVE, SINALOA", RED)
    cv.circle(x + 252, y + 88, 13, GOLD)
    cv.circle(x + 288, y + 70, 13, GOLD)
    for cx, cy, ch in ((x + 252, y + 88, "$"), (x + 288, y + 70, "5")):
        ww = tx.width("sansb15", ch)
        tx.draw(cv, "sansb15", cx - ww // 2, cy - 8, ch, INK)


LEAD_X = [12, 350, 688]
MED_X = [12, 180, 348, 516, 684, 852]
TICKS = [170, 323, 476, 629, 782, 935]
MAP_X, MAP_Y, MAP_W, MAP_H = 12, 628, 330, 166
MAP_LAT_TOP, MAP_LAT_BOT = 84, -58


def map_xy(lon, lat):
    mx = MAP_X + int((lon + 180) * MAP_W / 360)
    my = MAP_Y + int((MAP_LAT_TOP - lat) * MAP_H
                     / (MAP_LAT_TOP - MAP_LAT_BOT))
    return mx, my


def draw(cv, tx):
    assert len(LEADS) == 3 and len(MEDIUM) == 12
    assert len(LIST_A) + len(LIST_B) == 39
    total = 3 + 12 + 39

    # ---- kicker
    tx.draw(cv, "sansb10", 12, 2, "THE WORLD'S NEWS OF ONE DAY", RED)
    right = "54 STORIES \u00b7 7 REGIONS \u00b7 ALL FROM THIS SUNDAY"
    tx.draw(cv, "sans10", 1012 - tx.width("sans10", right), 2, right, INK)

    # ---- masthead
    head = "Sunday 22 November 2026"
    tx.draw(cv, "serif48", (W - tx.width("serif48", head)) // 2, 16,
            head, INK)
    cv.hline(12, 1012, 72, INK, 2)
    cv.hline(12, 1012, 75, INK, 1)

    # ---- timeline
    tx.draw(cv, "sansb10", 12, 80, "THE DAY IN UTC", RED)
    cv.hline(140, 980, 99, INK, 1)
    for (tm, ev), cx in zip(TIMELINE, TICKS):
        cv.vline(cx, 95, 103, INK, 1)
        tx.draw(cv, "sansb10", cx - tx.width("sansb10", tm) // 2, 82,
                tm, INK)
        tx.draw(cv, "sans10", cx - tx.width("sans10", ev) // 2, 102,
                ev, INK)

    # ---- leads
    arts = [draw_lead_art1, draw_lead_art2, draw_lead_art3]
    for i, (cat, headline, body, src) in enumerate(LEADS):
        x = LEAD_X[i]
        if i == 2:
            arts[i](cv, tx, x, 118, 324, 112)
        else:
            arts[i](cv, x, 118, 324, 112)
        frame(cv, x, 118, 324, 112, INK)
        tx.draw(cv, "sansb10", x, 236, cat, RED)
        lines = tx.wrap("sansb22", headline, 324)[:3]
        for j, ln in enumerate(lines):
            tx.draw(cv, "sansb22", x, 252 + j * 26, ln, INK)
        for j, ln in enumerate(tx.wrap("sans12", body, 324)[:2]):
            tx.draw(cv, "sans12", x, 332 + j * 15, ln, INK)
        tx.draw(cv, "sans10", x, 364, src, GREY)
    cv.hline(12, 1012, 382, INK, 1)

    # ---- medium stories, 6 columns x 2 rows
    for idx, (cat, headline, detail, src, icon) in enumerate(MEDIUM):
        col, row = idx % 6, idx // 6
        x = MED_X[col]
        y0 = 388 + row * 110
        draw_icon(cv, icon, x, y0)
        tx.draw(cv, "sansb10", x + 34, y0 + 8, cat, RED)
        for j, ln in enumerate(tx.wrap("sansb15", headline, 160)[:2]):
            tx.draw(cv, "sansb15", x, y0 + 32 + j * 17, ln, INK)
        for j, ln in enumerate(tx.wrap("sans10", detail, 160)[:2]):
            tx.draw(cv, "sans10", x, y0 + 68 + j * 12, ln, INK)
        tx.draw(cv, "sans10", x, y0 + 92, src, GREY)
    cv.hline(12, 1012, 606, INK, 1)

    # ---- bottom section headers
    tx.draw(cv, "sansb10", 12, 612, "WHERE IT HAPPENED", RED)
    tx.draw(cv, "sansb10", 354, 612, "AMERICAS \u00b7 AFRICA \u00b7 MIDDLE EAST",
            RED)
    tx.draw(cv, "sansb10", 676, 612, "EUROPE \u00b7 ASIA \u00b7 MARKETS", RED)
    cv.vline(348, 612, 1000, GREY, 1)
    cv.vline(672, 612, 1000, GREY, 1)

    # ---- world map
    cv.rect(MAP_X, MAP_Y, MAP_W, MAP_H, OCEAN)
    grid = (198, 216, 222)
    for lon in range(-150, 181, 30):
        gx, _ = map_xy(lon, 0)
        cv.vline(gx, MAP_Y, MAP_Y + MAP_H, grid, 1)
    for lat in (60, 30, 0, -30):
        _, gy = map_xy(0, lat)
        cv.hline(MAP_X, MAP_X + MAP_W, gy, grid, 1)
    for poly_lonlat in CONTINENTS:
        cv.poly([map_xy(lon, lat) for lon, lat in poly_lonlat], LAND)
    frame(cv, MAP_X, MAP_Y, MAP_W, MAP_H, INK)
    for num, lon, lat, dx, dy in MAP_DOTS:
        tx0, ty0 = map_xy(lon, lat)
        cx, cy = tx0 + dx, ty0 + dy
        if dx or dy:
            cv.line(tx0, ty0, cx, cy, INK)
            cv.circle(tx0, ty0, 2, RED)
        cv.circle(cx, cy, 7, RED)
        label = str(num)
        tx.draw(cv, "sansb10", cx - tx.width("sansb10", label) // 2,
                cy - 6, label, WHITE)
    for j, ln in enumerate(MAP_LEGEND):
        tx.draw(cv, "sans10", 12, 798 + j * 12, ln, INK)

    # ---- date check box
    frame(cv, 12, 850, 330, 150, INK)
    tx.draw(cv, "sansb10", 20, 856, "DATE CHECK \u2014 LEFT OUT AS OLDER NEWS",
            RED)
    for j, item in enumerate(DATECHECK):
        tx.draw(cv, "sans10", 20, 872 + j * 12, item, INK)

    # ---- list columns
    for col_x, items in ((354, LIST_A), (676, LIST_B)):
        for j, (text, src) in enumerate(items):
            y = 634 + j * 17
            cv.rect(col_x, y + 4, 9, 3, RED)
            cv.rect(col_x, y + 7, 9, 3, NAVY)
            nx = tx.draw(cv, "sans12", col_x + 13, y, text, INK)
            tx.draw(cv, "sans12", nx, y, " [" + src + "]", GREY)

    # ---- footer
    cv.hline(12, 1012, 1006, GREY, 1)
    tx.draw(cv, "sans10", (W - tx.width("sans10", FOOTER)) // 2, 1010,
            FOOTER, GREY)
    return total


# ---------------------------------------------------------------- main
def build():
    fonts = _load_fonts()
    cv = Canvas(W, H, PAPER)
    tx = Text(fonts)
    total = draw(cv, tx)
    return encode_png(cv), total


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--output", "-o", default=None)
    ap.add_argument("--check", action="store_true",
                    help="render and validate without writing a file")
    args = ap.parse_args(argv)
    png, total = build()
    if len(png) > 1024 * 1024:
        print("FAIL: PNG is %d bytes, over the 1 MiB limit" % len(png),
              file=sys.stderr)
        return 1
    if args.check:
        print("CHECK OK: %d stories (3 leads + 12 medium + 39 list), "
              "1024x1024, PNG %d bytes (%.1f KB)"
              % (total, len(png), len(png) / 1024))
        return 0
    out = args.output
    if out is None:
        d = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
        out = os.path.join(d, "entry.png")
    parent = os.path.dirname(os.path.abspath(out))
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(out, "wb") as f:
        f.write(png)
    print("wrote %s (%d bytes, %.1f KB, %d stories)"
          % (out, len(png), len(png) / 1024, total))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
